-- Forms, "Request info" (docs/plan.md §1.115): one contact's copy of one form asked by a workflow
-- step, its saved draft, the answers sent and the documents uploaded through the public page. A new
-- table only, so the previous Worker keeps working. Generated by drizzle-kit; the grants and
-- row-level security at the end are hand-written.
CREATE TABLE "form_request" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"agent_id" uuid NOT NULL,
	"agent_version_id" uuid NOT NULL,
	"run_id" uuid NOT NULL,
	"step_run_id" uuid,
	"node_id" text NOT NULL,
	"contact_id" uuid NOT NULL,
	"reach_out_id" uuid,
	"purpose" text NOT NULL,
	"definition" jsonb NOT NULL,
	"ask" jsonb NOT NULL,
	"status" text NOT NULL,
	"language" text DEFAULT 'en' NOT NULL,
	"due_at" timestamp with time zone NOT NULL,
	"draft" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"answers" jsonb,
	"documents" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"sources" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"log" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"opened_at" timestamp with time zone,
	"submitted_at" timestamp with time zone,
	"run_received_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "form_request_id_tenant_key" UNIQUE("id","tenant_id"),
	CONSTRAINT "form_request_status_check" CHECK ("form_request"."status" in ('sending', 'open', 'submitted', 'expired', 'cancelled', 'not_sent')),
	CONSTRAINT "form_request_submitted_check" CHECK (("form_request"."status" = 'submitted') = ("form_request"."answers" is not null and "form_request"."submitted_at" is not null)),
	CONSTRAINT "form_request_purpose_check" CHECK (char_length("form_request"."purpose") between 1 and 500)
);
